S = "Hakeem Force Academy"
QS = [
(S, "What is the meaning of the word 'mitigate'?", ["To make less severe or serious", "To increase in size", "To delay on purpose", "To completely destroy"], 0, "To mitigate means to reduce the severity, seriousness or harm of something. For example, planting trees mitigates the effect of floods.", "Mitigation is a common word in disaster management, as in flood mitigation.", [3770]),
(S, "What is the meaning of the word 'recalcitrant'?", ["Stubbornly resisting authority or control", "Very generous", "Easily frightened", "Extremely clever"], 0, "A recalcitrant person obstinately refuses to obey rules or accept control. It is used for uncooperative people or animals.", "Its synonyms include defiant, unruly and obstinate.", [3774]),
(S, "What is the meaning of the verb 'rob'?", ["To take property unlawfully, often by force", "To repair something", "To pay back a loan", "To hide something safely"], 0, "To rob means to steal from a person or place, usually using force or threat. A person who does this is called a robber.", "Robbery differs from burglary because robbery involves force or threat against a person.", [3777]),
(S, "What is the meaning of the Urdu/Arabic word 'Seerat'?", ["Life history or biography", "Prayer", "Journey", "Charity"], 0, "Seerat means a person's life, conduct and character, and is used mainly for the biography of the Holy Prophet (PBUH). It is also written as Seerah.", "The earliest well-known Seerat of the Prophet (PBUH) was written by Ibn Ishaq and edited by Ibn Hisham.", [3778]),
(S, "What is the meaning of the word 'Tanzil' in Islamic terminology?", ["Revelation, sending down", "Migration", "Fasting", "Compilation"], 0, "Tanzil comes from the Arabic root meaning to send down, and is used for the revelation of the Quran. The Quran itself describes itself as Tanzil.", "Surah Ash-Shuara describes the Quran as a revelation (Tanzil) from the Lord of the worlds.", [1140]),
(S, "What is the meaning of the word 'Zamzam'?", ["Abundant, plentiful water", "A mountain", "A desert", "A city"], 0, "Zamzam is the name of the sacred well in Makkah, and the word is linked to plentiful, gushing water. The well sprang near the Kaaba for Hazrat Ismail (AS) and his mother Hazrat Hajra.", "Pilgrims drink Zamzam water during Hajj and Umrah, and Sai is performed between Safa and Marwa near it.", [3788]),
(S, "What is the meaning of the word 'Iltijaa'?", ["Humble request or plea", "Anger", "Victory", "Travel"], 0, "Iltijaa is an Urdu word of Arabic origin meaning a humble request, plea or entreaty. It is used for earnestly asking someone for help.", "Related words are darkhwast, arzi and dua, all meaning a request or prayer.", [3767]),
(S, "On which date did the Holy Prophet (PBUH) arrive in Madina after the Hijrat?", ["12 Rabi-ul-Awwal, 1 AH", "1 Muharram, 1 AH", "10 Ramadan, 2 AH", "27 Rajab, 1 AH"], 0, "After staying at Quba, the Prophet (PBUH) entered Madina on 12 Rabi-ul-Awwal, 1 AH (September 622 AD). He had left Makkah a few days earlier.", "Some sources give slightly different days for the departure and arrival, but 12 Rabi-ul-Awwal is the common Pakistani textbook date.", [999, 2877, 3587]),
(S, "In which year of prophethood (Nabawi year) did the Holy Prophet (PBUH) migrate from Makkah to Madina?", ["13th Nabawi", "10th Nabawi", "8th Nabawi", "15th Nabawi"], 0, "The Prophet (PBUH) received prophethood at about the age of 40 and migrated 13 years later. This corresponds to 622 AD and the first year of the Hijri calendar.", "The 10th year of prophethood is known as the Year of Grief because Hazrat Khadija (RA) and Abu Talib died.", [4208, 4236]),
(S, "What is the migration of the Holy Prophet (PBUH) from Makkah to Madina called?", ["Hijrat", "Mairaj", "Fatah", "Bait"], 0, "The migration from Makkah to Madina in 622 AD is called Hijrat (Hijrah). The Islamic Hijri calendar starts from this event.", "The Hijri calendar was introduced in the caliphate of Hazrat Umar (RA).", [1142]),
(S, "Who accompanied the Holy Prophet (PBUH) on his Hijrat from Makkah to Madina?", ["Hazrat Abu Bakr (RA)", "Hazrat Umar (RA)", "Hazrat Ali (RA)", "Hazrat Usman (RA)"], 0, "Hazrat Abu Bakr (RA) travelled with the Prophet (PBUH) and they hid in the Cave of Thawr. Hazrat Ali (RA) stayed behind in the Prophet's bed to return the trusts.", "Abdullah bin Uraiqit guided them on the route to Madina.", [5332]),
(S, "What is the median of the data 2, 2, 3, 3, 5, 6, 7, 8, 8?", ["5", "3", "6", "4.5"], 0, "The data is already in order and has 9 values, so the median is the 5th value. The 5th value is 5.", "The median is the middle value of ordered data, and for an even count it is the mean of the two middle values.", [417]),
(S, "What is the median of 2, 3, 5, 7?", ["4", "3", "5", "3.5"], 0, "There are 4 values, so the median is the mean of the two middle values 3 and 5. (3 + 5) / 2 = 4.", "The mean of 2, 3, 5, 7 is 4.25, which differs from the median.", [3792]),
(S, "What is the median of 3, 4, 7, 8, 6?", ["6", "7", "5.6", "4"], 0, "Arrange in order: 3, 4, 6, 7, 8. There are 5 values, so the median is the 3rd value, which is 6.", "The mean of these numbers is 5.6, not the median.", [3793]),
(S, "Which type of medicine is used to relieve pain?", ["Analgesic", "Antibiotic", "Antiseptic", "Antacid"], 0, "Analgesics such as paracetamol and aspirin are painkillers. They reduce pain without making the person lose consciousness.", "Anaesthetics are different because they cause loss of sensation before surgery.", [4715, 4716, 4717]),
(S, "How many members does SAARC have?", ["8", "7", "9", "10"], 0, "SAARC has eight members: Afghanistan, Bangladesh, Bhutan, India, Maldives, Nepal, Pakistan and Sri Lanka. Afghanistan joined as the eighth member in 2007.", "SAARC began in 1985 with seven founding members, and its secretariat is in Kathmandu.", [168]),
(S, "On what date did Pakistan become a member of SAARC?", ["8 December 1985 (as a founding member)", "1 January 1990", "8 December 2007", "14 August 1980"], 0, "Pakistan was one of the seven founding members of SAARC at the Dhaka summit on 8 December 1985. It did not join later.", "Afghanistan became the eighth member in April 2007.", [2875]),
(S, "How many seats does the Provincial Assembly of the Punjab have in total?", ["371", "297", "336", "342"], 0, "The Punjab Assembly has 297 general seats, 66 seats for women and 8 for non-Muslims. Together this makes 371.", "Punjab has the largest provincial assembly in Pakistan.", [2186, 624]),
(S, "What is the total number of seats in the National Assembly of Pakistan?", ["336", "342", "272", "372"], 0, "After the 25th Amendment merged FATA into Khyber Pakhtunkhwa, the total fell to 336 seats. These are 266 general, 60 women and 10 minority seats.", "Before this change the National Assembly had 342 seats.", [1198]),
(S, "How many member states does the United Nations have?", ["193", "190", "195", "185"], 0, "The UN has 193 member states. South Sudan was the latest to join, in 2011.", "The Holy See and Palestine are non-member observer states.", [2188]),
(S, "Which country voted against the admission of Pakistan to the United Nations in 1947?", ["Afghanistan", "India", "Iran", "Saudi Arabia"], 0, "Afghanistan was the only country that voted against Pakistan's admission to the UN in September 1947. It reversed its stand soon afterwards.", "Pakistan became the 56th member of the UN on 30 September 1947.", [4498, 1437]),
(S, "How many times is the name 'Muhammad' mentioned in the Holy Quran?", ["4", "2", "5", "25"], 0, "The name Muhammad appears 4 times in the Quran: in Surah Al-Imran, Al-Ahzab, Muhammad and Al-Fath. The name Ahmad appears once, in Surah As-Saff.", "Counts of other words vary a little by method, but 4 is the standard answer for the name Muhammad.", [2272, 2273]),
(S, "Which names of the Holy Prophet (PBUH) are mentioned in the Quran?", ["Muhammad and Ahmad", "Mustafa and Mahmood", "Hamid and Khatim", "Taha and Mujtaba"], 0, "The Quran directly uses the names Muhammad (four times) and Ahmad (once, in Surah As-Saff). Other titles like Taha and Yasin are separate.", "The Prophet (PBUH) is also addressed in the Quran with titles such as Nabi and Rasool.", [4733]),
(S, "Which companion (Sahabi) of the Holy Prophet (PBUH) is mentioned by name in the Quran?", ["Hazrat Zaid bin Haritha (RA)", "Hazrat Abu Bakr (RA)", "Hazrat Umar (RA)", "Hazrat Ali (RA)"], 0, "Only Hazrat Zaid bin Haritha (RA) is named in the Quran, in Surah Al-Ahzab, verse 37. Other great companions are referred to without their names.", "Abu Bakr (RA) is referred to as Sani-ithnain (second of the two) in Surah At-Tawbah.", [116]),
(S, "Which woman is mentioned by name in the Holy Quran?", ["Hazrat Maryam (AS)", "Hazrat Khadija (RA)", "Hazrat Aisha (RA)", "Hazrat Fatima (RA)"], 0, "Hazrat Maryam (AS), the mother of Hazrat Isa (AS), is the only woman named in the Quran. A whole surah is named after her.", "Her name appears about 34 times in the Quran.", [4975]),
(S, "In which year was the North-West Frontier Province (NWFP) renamed Khyber Pakhtunkhwa?", ["2010", "2001", "1973", "2018"], 0, "The 18th Amendment passed in April 2010 renamed NWFP as Khyber Pakhtunkhwa. Pakistan's parliament approved it that year.", "The former FATA was merged into Khyber Pakhtunkhwa in 2018 through the 25th Amendment.", [1244]),
(S, "How many metres are there in 2 km?", ["2000", "200", "20000", "20"], 0, "1 km = 1000 m, so 2 km = 2 x 1000 = 2000 m.", "One kilometre is about 0.62 miles.", [2192]),
(S, "In which city of Pakistan was the first Metro Bus service inaugurated?", ["Lahore", "Rawalpindi", "Karachi", "Multan"], 0, "The Metro Bus Service was inaugurated in Lahore in February 2013. It runs between Gajju Matta and Shahdara.", "Rawalpindi-Islamabad followed in 2015 and Multan in 2017.", [819, 529, 2555]),
(S, "Who is the youngest Microsoft Certified Professional from Pakistan?", ["Arfa Karim", "Malala Yousafzai", "Nergis Mavalvala", "Sharmeen Obaid-Chinoy"], 0, "Arfa Karim Randhawa became a Microsoft Certified Professional at the age of nine in 2004. She was the youngest in the world at that time.", "She died in 2012 and the Arfa Karim Software Technology Park in Lahore is named after her.", [5199, 5200]),
(S, "What is the midpoint of the points (3, 1) and (-3, 1)?", ["(0, 1)", "(3, 1)", "(0, 0)", "(1, 0)"], 0, "Midpoint = ((3 + (-3)) / 2, (1 + 1) / 2) = (0, 1).", "The midpoint formula is the average of the x values and the average of the y values.", [344]),
(S, "What is the midpoint of the points (4, 6) and (2, 6)?", ["(3, 6)", "(6, 12)", "(3, 12)", "(2, 6)"], 0, "Midpoint = ((4 + 2) / 2, (6 + 6) / 2) = (3, 6).", "Both points have the same y value, so the segment is horizontal.", [3794]),
(S, "What is the meaning of 'broke down' in the sentence: The car broke down one mile away from home?", ["Stopped working", "Went very fast", "Was sold", "Was painted"], 0, "To break down means a machine or vehicle stops working because of a fault. So the car stopped working one mile from home.", "Break down can also mean to lose emotional control or to analyse something in parts.", [3737]),
(S, "Which country has the largest number of active military personnel in the world?", ["China", "India", "United States", "Russia"], 0, "China's People's Liberation Army has about two million active personnel, the most in the world. India and the United States follow.", "Rankings change slowly, and India has the second-largest active force in most recent lists.", [4513]),
(S, "Which of the following is a military alliance?", ["NATO", "SAARC", "OPEC", "WTO"], 0, "NATO (North Atlantic Treaty Organization) is a collective defence military alliance founded in 1949. SAARC is regional cooperation, OPEC deals with oil and WTO with trade.", "Its Article 5 says an attack on one member is an attack on all.", [4602]),
(S, "Why do we boil milk?", ["To kill germs", "To increase fat", "To remove calcium", "To add protein"], 0, "Boiling heats the milk enough to destroy harmful bacteria and other germs. This makes it safe to drink.", "Pasteurization is a milder heat treatment named after Louis Pasteur.", [5462]),
(S, "How many sugar mills did Pakistan have at the time of independence in 1947?", ["2", "5", "10", "20"], 0, "Most colonial-era sugar mills were on the Indian side, and Pakistan had only two sugar mills in 1947. The first new mill came later in Sindh.", "Pakistan now has dozens of sugar mills and is a major sugarcane grower.", [1777, 516]),
(S, "According to the 1973 Constitution, what is the minimum age to become a member of the National Assembly of Pakistan?", ["25 years", "21 years", "30 years", "35 years"], 0, "Article 62 requires a candidate for the National Assembly to be at least 25 years old. A voter must be 18.", "Candidates for the Senate must be at least 30 years old.", [751]),
(S, "What is the minimum age to become President of Pakistan?", ["45 years", "35 years", "40 years", "50 years"], 0, "Article 41 of the 1973 Constitution says the President must be a Muslim, qualified to be a National Assembly member and at least 45 years old.", "The President is elected by an electoral college of Parliament and the provincial assemblies.", [3796]),
]
